I think @francoischalifour was thinking about an integration test closer to the real usage from a user POV.

Here's an example using testing-libary: 

```js
import { wait, getByLabelText } from '@testing-library/dom';

import instantsearch from '../../../';

import apiResults from './__fixtures__/api-results.json';

describe('infiniteHits', () => {
  let search;
  let searchClient;

  beforeEach(() => {
    searchClient = {
      search: jest.fn(() => Promise.resolve(apiResults)),
    };

    search = instantsearch({
      indexName: 'instant_search',
      searchClient,
    });
  });

  afterEach(() => {
    try {
      search.dispose();
    } catch (e) {
      // Fail if the search was never started, ignoring
    }
  });

  it('must hit cache when navigating to a previously visited page', async () => {
    const infiniteHitsContainer = document.createElement('div');
    const paginationContainer = document.createElement('div');

    const customCache = {
      read: jest.fn(() => {
        // Your custom read implementation
      }),
      write: jest.fn(() => {
        // Your custom write implementation
      }),
    };

    search.addWidgets([
      instantsearch.widgets.infiniteHits({
        container: infiniteHitsContainer,
        cache: customCache,
      }),
      instantsearch.widgets.pagination({
        container: paginationContainer,
        scrollTo: false,
      }),
    ]);

    search.start();

    await wait();

    // Assert that the client was called (page 1 was not cached)
    expect(searchClient.search).toBeCalledTimes(1);

    // Navigate to page 2
    getByLabelText(paginationContainer, 'Next').click();

    await wait();

    // Assert that the client was called (page 2 was not cached)
    expect(searchClient.search).toBeCalledTimes(2);

    // Navigate to page 1
    getByLabelText(paginationContainer, 'Previous').click();

    await wait();

    // Assert that the client was not called (page 1 was cached)
    expect(searchClient.search).toBeCalledTimes(2);
  });
});
```
